import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const m=JSON.parse('{"title":"术语表","description":"","frontmatter":{"title":"术语表"},"headers":[],"relativePath":"vision-rag-course/glossary.md","filePath":"vision-rag-course/docs/glossary.md"}'),o={name:"vision-rag-course/glossary.md"};function s(n,t,i,l,c,p){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>全书首教过的术语，按首次出现的大致顺序整理成表。定义就是正文首现时那句人话。</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话定义</th></tr></thead><tbody><tr><td>视觉大模型</td><td>Vision Language Model / VLM</td><td>能同时读文字和图片、就内容对话的大模型——一位看得见照片的远程助手。</td></tr><tr><td>多模态</td><td>multimodal</td><td>一个模型同时处理多种信息类型（文字加图片），而不是只会读纯文本。</td></tr><tr><td>上下文窗口</td><td>context window</td><td>模型一次调用里能摊开读的全部内容上限——助手桌面就这么大，塞满就放不下。</td></tr><tr><td>检索增强生成</td><td>RAG</td><td>先从资料里找出相关内容、再让模型照着找到的部分回答——开卷考试，不是闭卷背诵。</td></tr><tr><td>成本漏斗</td><td></td><td>三层筛选结构：免费的本地粗筛先圈候选，便宜的模型调用再精选，昂贵的深读只留给最后几页。</td></tr><tr><td>幻觉</td><td>hallucination</td><td>模型一本正经编造不存在的内容或出处——考试不会答还硬编页码。</td></tr><tr><td>API 密钥</td><td>API key</td><td>调云端服务时的身份凭证，像门禁卡——随身带，但绝不能写死在要公开的代码里。</td></tr><tr><td>base64</td><td></td><td>把图片的字节编码成纯文本的办法，让一次请求里能「随身带图」；拼上 data: 前缀就成了内联的数据地址。</td></tr><tr><td>系统提示词</td><td>system prompt</td><td>调用模型时预先给它的岗位说明书，规定角色、任务与输出格式。</td></tr><tr><td>推理强度</td><td>reasoning effort</td><td>模型下笔前「想多深」的档位——批量打标用低档省时省钱，深读分析用高档。</td></tr><tr><td>指数退避</td><td>exponential backoff</td><td>失败重试的节奏：等 2 秒、再败等 4 秒、再败等 8 秒——越挫越客气，不把对方打挂。</td></tr><tr><td>JSON 围栏</td><td></td><td>模型爱把 JSON 包进三个反引号的代码块再输出，像礼物装了包装盒——解析前要先拆盒。</td></tr><tr><td>DPI</td><td>dots per inch</td><td>每英寸多少个点，渲染清晰度的旋钮——数字越大图越清楚，进模型的账单也越贵。</td></tr><tr><td>文字层</td><td></td><td>PDF 里机器可直接抽出的那层文字。真排版的 PDF 有；扫描件只有照片、这层是空的。</td></tr><tr><td>按分辨率计费</td><td></td><td>图片进视觉模型按像素量收费的计费方式——图越清晰越贵，清晰度是成本旋钮。</td></tr><tr><td>对半拆批</td><td></td><td>一批任务输出超长被截断时，把批对半分成两批递归重试——总能装得下。</td></tr><tr><td>分词</td><td>tokenization</td><td>把连成一串的中文切成可检索的小块——中文没有空格，得自己切（本课程用相邻两字滑窗）。</td></tr><tr><td>停用词</td><td>stop words</td><td>「什么」「怎么」这类到处都有、不携带线索的词，检索前先扔掉。</td></tr><tr><td>TF-IDF</td><td>term frequency–inverse document frequency</td><td>给词打分的检索方法：在这页出现越多、在全书出现越少的词越值钱。</td></tr><tr><td>词面匹配</td><td></td><td>只对字面的检索方式：问「退货」就匹配不到只写「退换」的页——它的盲区正是要加视觉精排的原因。</td></tr><tr><td>top-k</td><td></td><td>只取排分最高的前 k 名——筛候选人筛页面都用它。</td></tr><tr><td>回退</td><td>fallback</td><td>高档手段失败时退回低档手段保命的策略：模型精排失败就退回本地排序，功能不断。</td></tr><tr><td>邻页</td><td></td><td>命中页的前后一页。表格和论证常跨页断开，深读要带上邻页才不被半截信息带偏。</td></tr><tr><td>拒答</td><td></td><td>证据不足时明确说「资料里没有、缺什么」，而不是编一段——被设计出来的诚实行为。</td></tr><tr><td>正则表达式</td><td>regular expression</td><td>按格式捞文本的渔网：网眼写成「第＋数字＋页」就能从一段话里捞出所有页码引用。</td></tr><tr><td>自包含 HTML</td><td></td><td>把答案、引用、证据图全部内嵌进单个 HTML 文件——双击即开，不依赖任何外部文件。</td></tr><tr><td>抽帧</td><td>frame extraction</td><td>按固定间隔把视频抽成一张张带时刻标签的图片——视觉模型看视频就是看这叠连环画。</td></tr><tr><td>采样密度</td><td>sampling fps</td><td>每秒抽几帧。抽得密看得清但贵，抽得疏省钱但可能漏掉瞬间——按时长分档权衡。</td></tr><tr><td>场景切换</td><td>scene cut</td><td>画面内容明显突变的时刻（换镜头），可用程序在本地检测出来当切分线。</td></tr><tr><td>段聚合</td><td></td><td>把零散的帧卡片按时长归堆成段卡片（如每 30 秒一段），检索粒度从帧升到段。</td></tr><tr><td>运动强度</td><td></td><td>帧卡片上顺手记录的「画面动得猛不猛」等级——微观放大层靠它找最值得拉近看的时刻。</td></tr><tr><td>时间戳</td><td>timestamp</td><td>某画面在视频里的时刻，分:秒写作 [01:23]——视频回答里的「页码」。</td></tr><tr><td>关键帧</td><td>keyframe</td><td>能代表一段内容的画面，比如段中间时刻那一帧——一段戏的剧照。</td></tr><tr><td>微观层</td><td></td><td>对可疑时间窗用高得多的采样密度（如 12fps）重新看一遍的两级设计——望远镜扫全景、显微镜看疑点。</td></tr><tr><td>中心裁切</td><td>center crop</td><td>把画面中间一块挖出来单独送模型——同样的分辨率下细节翻倍，是「放大看」的实现手段。</td></tr><tr><td>锚点帧</td><td></td><td>微观帧序列开头放的一张全图，防止只看放大画面丢失位置感——放大镜旁钉的全景小地图。</td></tr><tr><td>双引擎互验</td><td></td><td>同一素材让两个不同厂商的模型各答一遍、对照答案——重要结论问两位专家。</td></tr><tr><td>agent skill</td><td></td><td>写给 AI 助手的工具说明书文件（含触发条件与工作流），让助手在合适的时机自动调用你的脚本。</td></tr><tr><td>渐进披露</td><td>progressive disclosure</td><td>说明书只放一页精要、细节文档按需再读的文档组织法——省上下文预算，像分层抽屉。</td></tr><tr><td>环境变量</td><td></td><td>操作系统给每个进程看的随身配置表——密钥这类敏感值放这里，代码里只写名字不写值。</td></tr><tr><td>扫描版</td><td></td><td>纸质文档拍照或扫描成的 PDF 页——只有图像没有文字层，机器抽不出字，只能靠看图。</td></tr><tr><td>截断</td><td>finish reason: length</td><td>输出长度超出预算被拦腰砍断——批的答案装不下时的结构性故障，重试救不了，只能拆批。</td></tr><tr><td>文字层兜底</td><td></td><td>模型反复读不出的页退而用文字层开头凑一张弱卡占位——整本不中断，弱页事后定向补。</td></tr><tr><td>触发描述</td><td></td><td>技能说明头部那段「用户提到 X 且想做 Y 时用本工具」的自然话说明——AI 助手靠它判断何时掏出这个工具。</td></tr></tbody></table>',3)])])}const _=d(o,[["render",s]]);export{m as __pageData,_ as default};
